exercises.solution:
using System;

public class Program
{
    public static void Main()
    {
        Console.WriteLine(Fibonacci(6));
        Console.WriteLine(Fibonacci(10));
    }

    static long Fibonacci(int n)
    {
        if (n <= 1) return n;
        long a = 0, b = 1;
        for (int i = 2; i <= n; i++)
        {
            long p = a + b; a = b; b = p;
        }
        return b;
    }
}

