using System;

public class Program
{
    public static void Main()
    {
        for (int i = 1; i <= 15; i++)
            Console.WriteLine(FizzBuzz(i));
    }

    static string FizzBuzz(int n)
    {
        if (n % 15 == 0) return "FizzBuzz";
        if (n % 3 == 0) return "Fizz";
        if (n % 5 == 0) return "Buzz";
        return n.ToString();
    }
}

